class Solution {
    public:long long minimumTotalDistance(vector<int>& robot,vector<vector<int>>& factory){
        sort(robot.begin(),robot.end());
        sort(factory.begin(),factory.end());
        int m=robot.size();
        const long long inf=LLONG_MAX/4;
        vector<long long> dp(m+1,inf);
        dp[0]=0;
        for(auto& current:factory){
            vector<long long> next=dp;
            for(int i=1;i<=m;++i){
                long long distance=0;
                for(int take=1;take<=current[1]&&take<=i;++take){
                    distance+=llabs((long long)robot[i-take]-current[0]);
                    if(dp[i-take]<inf)next[i]=min(next[i],dp[i-take]+distance);
                }
            }
            dp.swap(next);
        }
        return dp[m];
    }
};
